"use client";

import { createContext, useCallback, useContext, useEffect, useState } from "react";
import { onAuthStateChanged, signOut as firebaseSignOut, type User } from "firebase/auth";
import { getClientAuth } from "@/lib/firebaseClient";

interface Profile {
  role: "user" | "admin";
  phoneVerified: boolean;
}

interface AuthContextValue {
  user: User | null;
  profile: Profile | null;
  loading: boolean;
  isAdmin: boolean;
  /** True only for Google/Facebook sign-ins that haven't linked a phone number yet. */
  needsPhoneVerification: boolean;
  refreshProfile: () => Promise<void>;
  signOut: () => Promise<void>;
}

const AuthContext = createContext<AuthContextValue>({
  user: null,
  profile: null,
  loading: true,
  isAdmin: false,
  needsPhoneVerification: false,
  refreshProfile: async () => {},
  signOut: async () => {},
});

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [loading, setLoading] = useState(true);

  const fetchProfile = useCallback(async () => {
    try {
      const res = await fetch("/api/me", { cache: "no-store" });
      const data = await res.json();
      setProfile(
        data.user ? { role: data.user.role, phoneVerified: data.user.phoneVerified } : null
      );
    } catch {
      setProfile(null);
    }
  }, []);

  useEffect(() => {
    const unsubscribe = onAuthStateChanged(getClientAuth(), async (currentUser) => {
      setUser(currentUser);
      if (currentUser) {
        await fetchProfile();
      } else {
        setProfile(null);
      }
      setLoading(false);
    });
    return unsubscribe;
  }, [fetchProfile]);

  async function signOut() {
    await firebaseSignOut(getClientAuth());
    await fetch("/api/auth/session", { method: "DELETE" });
    setUser(null);
    setProfile(null);
  }

  const isOAuthOnly = !!user && user.providerData.every((p) => p.providerId !== "password");
  const phoneConfirmed = profile?.phoneVerified ?? Boolean(user?.phoneNumber);
  const needsPhoneVerification = isOAuthOnly && !phoneConfirmed;

  return (
    <AuthContext.Provider
      value={{
        user,
        profile,
        loading,
        isAdmin: profile?.role === "admin",
        needsPhoneVerification,
        refreshProfile: fetchProfile,
        signOut,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => useContext(AuthContext);
